mapper.insert:
insert into sale_payment_order (
    payment_order_no, order_no, student_code, student_name, phone, product_name, payment_amount,
    payment_channel, payment_status, cashier_url, expires_at, merchant_no, created_at, updated_at
) values (
    #{paymentOrderNo}, #{orderNo}, #{studentCode}, #{studentName}, #{phone}, #{productName}, #{paymentAmount},
    #{paymentChannel}, #{paymentStatus}, #{cashierUrl}, #{expiresAt}, #{merchantNo}, #{createdAt}, #{updatedAt}
)

mapper.select:
select cashier_url, expires_at, merchant_no, id, payment_order_no, order_no, student_code, student_name, phone, product_name, payment_amount, payment_channel, payment_status, unique_order_no, last_error_msg, created_at, updated_at from sale_payment_order
and ( payment_order_no like concat('%', #{keyword}, '%') or order_no like concat('%', #{keyword}, '%') or student_code like concat('%', #{keyword}, '%') or student_name like concat('%', #{keyword}, '%') or phone like concat('%', #{keyword}, '%') or product_name like concat('%', #{keyword}, '%') or ifnull(unique_order_no, '') like concat('%', #{keyword}, '%') )
and payment_status = #{paymentStatus}
and payment_channel = #{paymentChannel}
order by id desc

mapper.update:
update sale_payment_order
set payment_status = #{toStatus},
    last_error_msg = null,
    updated_at = now()
where id = #{id}
  and payment_status = #{fromStatus}

update sale_payment_order
set payment_status = #{toStatus},
    last_error_msg = #{lastErrorMsg},
    updated_at = now()
where id = #{id}
  and payment_status = #{fromStatus}
